INSERT INTO `search_dataset` (`sid`, `langcode`, `type`, `data`, `reindex`) VALUES
(1, 'es', 'help_search', ' exportando la configuracion completa de su sitio objetivo create and download an archive containing all your site s configuration exported as yaml files see managing and deploying configuration for more information about configuration pasos en el menu administrativo administrar  vaya a configuracion   desarrollo   sincronizacion de configuracion   exportar  clique exportar y guarde el archivo  ', 0),
(1, 'es', 'node_search', ' noticia1 noticia1 admin sab 17102026 37 noticias ', 0),
(2, 'es', 'help_search', ' exportando un unico elemento de configuracion objetivo exporta un unico elemento de configuracion a un archivo consulte managing and deploying configuration para obtener mas informacion sobre la configuracion pasos en el menu administrativo administrar  vaya a configuracion   desarrollo   sincronizacion de configuracion   exportar   elemento unico  select the configuration type that you want to export and then select the specific configuration name to export use your browser to copy the text in the box marked here is your configuration to the clipboard paste the copied text into a plaintext editor on your computer or other device and save it using the suggested file name below the text box  ', 0),
(2, 'es', 'node_search', ' noticia2 noticia2 admin sab 17102026 45 noticias ', 0),
(3, 'es', 'help_search', ' importando la configuracion completa de su sitio objetivo importar la configuracion completa de su sitio desde un archivo como uno que haya sido exportado previamente ver exportando la configuracion completa de su sitio consulte managing and deploying configuration para obtener mas informacion sobre la configuracion pasos en el menu administrativo administrar  vaya a configuracion   desarrollo   sincronizacion de configuracion   importar  navegue para encontrar el archivo de configuracion que quiera importar click upload  your configuration archive will be unpacked and placed in the configuration synchronization directory and you will be redirected to the synchronize page review the differences between your uploaded configuration and the active configuration if any and click import all to import the changes  ', 0),
(3, 'es', 'node_search', ' noticia3 noticia3 admin sab 17102026 46 noticias ', 0),
(4, 'es', 'help_search', ' importando un unico elemento de configuracion objetivo importar un unico elemento de configuracion en formato yaml como uno que se haya exportado previamente vease exportando un unico elemento de configuracion consulte managing and deploying configuration para obtener mas informacion sobre la configuracion pasos en el menu administrativo administrar  vaya a configuracion   desarrollo   sincronizacion de configuracion   importar   elemento unico  select the configuration type that you want to import on your computer or other device copy the yamlformat configuration that you want to import to the clipboard paste the clipboard text into the box labeled paste your configuration here  clique importar   ', 0),
(4, 'es', 'node_search', ' video1 video1 admin sab 17102026 1851 video1 ', 0),
(5, 'es', 'help_search', ' managing the fields of contact forms objetivo agregue elimine o reorganice los campos en formularios de contacto personales y de todo el sitio  cuales son los campos de los formularios de contacto  both personal and sitewide contact forms will always have subject and message fields you can add additional fields for users to fill out if desired note that if you want to display other content on a form page such as text or images you can use a content block pasos en el menu administrativo administrar  vaya a estructura   formularios de contacto  click manage fields for the form you want to change the fields of and add or remove one or more fields on the form haga clic en administrar la pantalla del formulario para cambiar el orden o la configuracion de los campos en el formulario  ', 0),
(5, 'es', 'node_search', ' video1 video1 admin sab 17102026 1851 video ', 0),
(6, 'es', 'help_search', ' configuring personal contact forms objetivo configure personal contact forms for registered users on the website pasos en el menu administrativo administrar  vaya a configuracion   personas   configuracion de la cuenta  en la seccion configuracion de contacto  marque desmarque la casilla para habilitar deshabilitar el formulario de contacto para nuevas cuentas de usuario pulse guardar configuracion  en el menu administrativo administrar  vaya a personas   permisos  verify that permissions are correct for your site s roles including the generic anonymous user and authenticated user  in order to use personal contact forms users need both view user information  in the user section which enables them to view user profiles and use users personal contact forms  in the contact section which enables them to use contact forms if they can view user profiles clique guardar permisos  el formulario de contacto siempre tendra los campos asunto y mensaje  si desea agregar mas campos siga los pasos en managing the fields of contact forms  ', 0),
(6, 'es', 'node_search', ' video2 video2 admin sab 17102026 1902 video ', 0),
(7, 'es', 'help_search', ' creando un nuevo formulario de contacto objetivo create a new sitewide contact form pasos en el menu administrativo administrar  vaya a estructura   formularios de contacto  clique anadir formulario de contacto  fill in the label  title for the form  recipients  and optionally the other settings haga clic en guardar  deberia ver su nuevo formulario de contacto en la tabla junto con un enlace para verlo el formulario de contacto siempre tendra los campos asunto y mensaje  si desea agregar mas campos siga los pasos en managing the fields of contact forms  ', 0),
(7, 'es', 'node_search', ' video3 video3 admin sab 17102026 1902 video ', 0),
(8, 'es', 'help_search', ' gestionar formularios de contacto  que son los formularios de contacto  hay dos tipos diferentes de formularios de contacto proporcionados por el modulo de contacto central formularios de contacto personal que permiten a los usuarios contactar a otros usuarios en el sitio y formularios de contacto en todo el sitio que permiten a los usuarios comunicarse con los gerentes o administradores del sitio un sitio puede tener mas de un formulario de contacto en todo el sitio cada uno tiene sus propios campos para completar destinatarios y url tambien puede cambiar los campos que se muestran en formularios de contacto personal usando el formulario de contacto personal site visitors can email registered users on your site by using the personal contact form without knowing or learning the email address of the recipient when a user with the correct permissions is viewing another user s profile the viewer will see a contact tab or link which leads to the personal contact form if the user whose profile is being viewed has their personal contact form enabled this is a user account setting  tareas de gestion de formularios de contacto consulte los temas relacionados a continuacion para obtener tareas especificas  ', 0),
(8, 'es', 'node_search', ' foto1 foto1 admin sab 17102026 1903 galeria ', 0),
(9, 'es', 'help_search', ' setting a default contact form objetivo set a sitewide contact form to be the default contact form  the form displayed on the default contact page  for example   contact   pasos en el menu administrativo administrar  vaya a estructura   formularios de contacto  click edit for the sitewide form you want to be the default check make this the default form and click save   ', 0),
(9, 'es', 'node_search', ' foto2 foto2 admin sab 17102026 1927 galeria ', 0),
(10, 'es', 'help_search', ' cambiando el aspecto de su pagina web  que es un tema  a theme is a set of files that define the visual look and feel of your site the core software and modules that run on your site determine which content including html text and other data stored in the database uploaded images and any other asset files is displayed on the pages of your site the theme determines the html markup and css styling that wraps the content several basic themes are supplied with the core software additional contributed themes can be downloaded separately from the download extend page on drupalorg  or you can create your own theme  que es un tema base  a base theme is a theme that is not meant to be used directly on a site but instead acts as a scaffolding for building other themes the core stable 9 theme is one example other base themes can be downloaded from the download extend page on drupalorg   que es un layout diseno  a layout is a template that defines where blocks and other pieces of content should be displayed the core layout discovery module allows modules and themes to register layouts and the core layout builder module provides a visual interface for placing fields and blocks in layouts for entity subtypes and individual entity items see managing content structure for more on entities and fields  changing site appearance overview la principal forma de cambiar la apariencia general de su sitio es cambiar el tema por defecto los modulos centrales layout builder y layout discovery le permiten definir disenos para el contenido de su sitio y el modulo central breakpoint ayuda a los temas a cambiar la apariencia para dispositivos de diferentes tamanos consulte los temas relacionados que se enumeran a continuacion para conocer las tareas especificas recursos adicionales extending and customizing your site drupal user guide  theming drupal ', 0),
(10, 'es', 'node_search', ' foto3 foto3 admin sab 17102026 1927 galeria ', 0),
(11, 'es', 'help_search', ' managing and deploying configuration what is the configuration system  the configuration system provides the ability for administrators to customize the site and to move and synchronize configuration changes between development sites and the live site it does this in 2 ways providing storage for configuration providing a process in which configuration changes can be imported and exported between instances of the same site for example from dev to staging to live  what is configuration data  configuration data describes settings that define how your site behaves or is displayed for example when a site administrator updates settings using an administrative form these settings are stored as configuration data configuration data describes settings as simple as a site name and as complex as a view or image style what kinds of configuration are there  active configuration active configuration is the current working configuration of a site storage of active configuration is defined by the site and resides in the database by default configuracion sencilla a simple configuration item is a group of settings such as the settings for a module or theme each simple configuration item has its own unique structure entidades de configuracion las entidades de configuracion son elementos de configuracion definidos por el usuario y agrupados por tipo tales como vistas estilos de imagen y tipos de contenido cada entidad de configuracion dentro de un tipo tiene una estructura similar configuracion predeterminada default configuration can be defined by a module theme or installation profile in its config install or config optional directories configuration is provided in yaml files file extension yml yaml is a humanreadable data serialization standard that is used by the core software for several purposes once the default configuration has been imported into the site s active configuration through installing the extension that configuration is owned by the site not the extension this means that future updates of the extension will not override the site s active configuration for that extension what is configuration synchronization  configuration synchronization is the process of exporting and importing configuration to keep configuration synchronized between different versions of a site for example between a development site and the live site each site has unique identifier also called a uuid  which identifies the site to the system in any instance of the site as long as the site instances have been reproduced as clones cloning is when the codebase and database are copied to create a new site instance when site instances are cloned a dev instance of the site has the same uuid as the live instance when site instances share the same uuid configuration can be exported from one instance to another the following list contains terms and concepts related to configuration synchronization exported configuration when configuration is exported the active configuration is exported as a set of files in yaml format when using the configuration synchronization administrative ui configuration can be exported as a fullexport or singleitem archive this archive can then be imported into the destination site instance imported configuration imported configuration is configuration that has been exported from another instance of the site the source and is now being imported into another site instance the destination thereby updating its active configuration to match the imported configuration data set directorio de sincronizacion de configuracion the configuration sync directory location is set in the site s settingsphp file when configuration is exported the active configuration is exported and described in yaml files which are stored in the configuration sync directory after the first export the system compares the site s active configuration with the configuration data in the sync directory and will only export active configuration items that are different than their counterparts in the sync directory managing configuration overview configuration management tasks such as exporting or importing configuration and synchronizing configuration can be done either through the administrative ui provided by the core configuration manager module or a commandline interface cli tool defining a configuration sync directory path other than the default value requires read write access to the site s settingsphp file most modules and themes also provide settings forms for updating the configuration they provide see the related topics listed below for specific tasks recursos adicionales configuration management workflow using drush concept types of data drupal user guide  concept development sites drupal user guide  making a development site drupal user guide  ', 0),
(12, 'es', 'help_search', ' managing content structure  que tipos de datos tiene un sitio  there are four main types of data content is the information text images etc meant to be displayed to website visitors configuration is data that defines how the content is displayed some configuration such as field labels may also be visible to site visitors state is temporary data about the state of your site such as the last time the system cron jobs ran session is a subset of state information related to users interactions with the site such as site cookies and whether or not they are logged in  que es una entidad de contenido  a content entity  or more commonly  entity  is an item of content data which can consist of text html markup images attached files and other data content entities are grouped into entity types  which have different purposes and are displayed in very different ways on the site most entity types are also divided into entity subtypes  which are divisions within an entity type to allow for smaller variations in how the entities are used and displayed for example the content item entity type that stores pagelevel content is divided into content type subtypes the content block entity type has block types  but the user entity type for user profile information does not have subtypes  que es un campo  within entity items the data is stored in individual fields  each of which holds one type of data such as formatted or plain text images or other files or dates fields can be added by an administrator on entity subtypes so that all entity items of a given entity subtype have the same collection of fields available and they can be singlevalued or multiplevalued when you create or edit entity items you are specifying the values for the fields on the entity item  que es un campo de referencia  un campo de referencia es un campo que almacena una relacion entre una entidad y una o mas entidades distintas que pueden pertenecer al mismo tipo de entidad o diferente por ejemplo un campo referencia de contenido en un tipo de contenido almacena una relacion entre un elemento de contenido y uno o mas elementos de contenido distintos  que tipos de campo estan disponibles  the following field types are provided by the core system and core modules many more are provided by contributed modules boolean number provided by the core system stores true false values and numbers comentario proporcionado por el modulo principal comment permite a los usuarios agregar comentarios a una entidad fecha marca de tiempo modulo datetime almacena fechas y horas intervalo de fechas modulo datetime range almacena periodos de hora fecha con un inicio y un final email core system stores email addresses link modulo link almacena urls y texto de enlace list options module stores values chosen from predefined lists where the values can be numbers or text see section below for more on list fields reference core system stores entity references see section above telefono modulo telephone almacena numeros de telefono text text module stores formatted and unformatted text see section below for more on text fields what settings are available for list field types  list fields associate predefined keys  or value codes with labels that the user sees for example you might define a list field that shows the user the names of several locations while behind the scenes a location code is stored in the database each list field type corresponds to one type of stored key for example a list integer  field stores integers while the list text  field stores text strings once you have chosen the field type the main setting for a list field is the allowed values list which associates the keys with the labels what types of text fields are available  there are several types of text fields with different characteristics text fields can be either plain or formatted  plain text fields do not contain html while formatted fields can contain html and are processed through text filters  these are provided by the core filter module if you have that module enabled see the related topic below on filters for more information text fields can also be regularlength with a limit of 255 characters or long  with a very large character limit and long formatted text fields can include a summary attribute all possible combinations of these characteristics exist as text field types for example  text plain  and text formatted long with summary  are two examples of text field types  que es un formateador  a formatter is a way to display a field most field types offer several types of formatters and most formatters have settings that further define how the field is displayed it is also possible to completely hide a field from display and you have the option of showing or hiding the field s label when it is displayed  que es un widget  a widget is a way to edit a field some field types such as plain text singleline fields have only one widget available in this case a singleline text input field other field types offer choices for the widget for example singlevalued list fields can use a select or radio button widget for editing many widget types have settings that further define how the field can be edited resumen de la administracion de la estructura del contenido besides the field modules listed in the previous section there are additional core modules that you can use to manage your content structure the core node comment content block custom menu links user file image media taxonomy and contact modules all provide content entity types the core field ui module provides a user interface for managing fields and their display on entities the core layout builder module provides a more flexible user interface for configuring the display of entities los modulos principales filter responsive image y path proporcionan configuraciones y opciones de visualizacion para entidades y campos depending on the core and contributed modules that you currently have installed on your site the related topics below and other topics listed on the main help page see ayuda will help you with tasks related to content structure recursos adicionales concept types of data drupal user guide  planning your site drupal user guide  concept reference fields drupal user guide  ', 0),
(13, 'es', 'help_search', ' running and configuring cron objetivo configure su sistema para que cron se ejecute automaticamente  que son las tareas cron  to ensure that your site and its modules continue to function well a group of administrative operations should be run periodically these operations are called cron tasks and running the tasks is known as running cron  depending on how often content is updated on your site you might need to run cron on a schedule ranging from hourly to weekly to keep your site running well  que opciones estan disponibles para ejecutar cron  if the core automated cron module is installed your site will run cron periodically on a schedule you can configure you can set up a task on your web server to visit the cron url  which is unique to your site on a schedule tambien puede ejecutar cron manualmente pero esta no es la forma recomendada de asegurarse de que se ejecute periodicamente pasos en el menu de administracion administrar  vaya a configuracion   sistema   cron  anote la hora de la ultima ejecucion en la pagina si desea ejecutar cron ahora mismo haga clic en ejecutar cron y espere a que termine cron if you have a way to configure tasks on your web server copy the link where it says to run cron from outside the site go to  set up a task to visit that url on your desired cron schedule such as once an hour or once a week on linuxlike servers you can use the wget command to visit a url if you configure an outside task you should uninstall the automated cron module si no esta configurando una tarea externa y tiene instalado el modulo principal automated cron seleccione un horario para las ejecuciones cron automatizadas en configuracion de cron  gt  ejecute cron cada  haz clic en guardar configuracion  recursos adicionales concept cron drupal user guide  configuring cron maintenance tasks drupal user guide  ', 0),
(14, 'es', 'help_search', ' extending and modifying your site functionality  que es un modulo  a module is a set of php javascript and or css files that extends site features and adds functionality a set of core modules is distributed as part of the core software download additional contributed modules can be downloaded separately from the download extend page on drupalorg   que es un modulo experimental  un modulo experimental es un modulo que todavia esta en desarrollo y aun no es estable no se recomienda el uso de modulos experimentales en sitios de produccion  que es instalar y desinstalar  installing a core or downloaded contributed module means turning it on so that you can use its features and functionality uninstalling means turning it off and removing all of its configuration a module cannot be uninstalled if another installed module depends on it or if you have created content on your site using the module you would need to delete the content and uninstall dependent modules first ampliacion de la descripcion general consulta los temas relacionados que se enumeran a continuacion para obtener ayuda sobre realizar tareas relacionadas con la ampliacion de la funcionalidad de tu sitio recursos adicionales concept modules drupal user guide  extending and customizing your site drupal user guide  ', 0),
(15, 'es', 'help_search', ' maintaining and troubleshooting your site descripcion general de mantenimiento y solucion de problemas here are some tasks and hints related to maintaining your site and troubleshooting problems that may come up on your site see the related topics below for more information when performing maintenance such as installing uninstalling or updating a module put your site in maintenance mode configure tu sitio para que cron se ejecute periodicamente si su web no se esta comportando como esperaba limpie la memoria cache de esta antes de intentar diagnosticar el problema there are several site reports that can help you diagnose problems with your site there are also two core modules that can be used for error logging database logging and syslog recursos adicionales preventing and fixing problems drupal user guide  security and maintenance drupal user guide  ', 0),
(16, 'es', 'help_search', ' managing media what are media items  core media items include audio images documents and videos you can add other media types such as social media posts through the use of contributed modules media items may be files located in your site s file system or remote items referenced by a url media items are content entities and they are divided into media types which are entity subtypes media types can have fields see managing content structure for more information on content entities and fields what is the media library  the media library is a visual user interface for managing and reusing media items add media items to content using media reference fields and the media library field widget what is an image style  an image style is a set of processing steps known as effects  that can be applied to images examples of effects include scaling and cropping images to different sizes responsive image styles can associate image styles with your theme s size breakpoints this allows serving images sized for the browser width overview of managing media the following modules provide mediarelated functionality media items and media types are managed by the core media module the core media module provides a media reference field to add media to content entities the core file and image modules also provide reference fields it is recommended to use the media reference field because it is more versatile the core media library module provides the media library and the media library field widget with this module installed the media library field widget becomes the default widget for editing media reference fields the core image module provides a user interface for defining image styles the core responsive image module provides responsive image styles using the core breakpoint module and a breakpointenabled theme these responsive styles can serve images sized for the browser consulte los temas relacionados listados a continuacion para tareas especificas recursos adicionales media module ', 0),
(17, 'es', 'help_search', ' gestionando menus  que es un menu  a menu is a collection of menu links used to navigate a web site menus and menu links can be provided by modules or site administrators managing menus overview the core menu ui module provides a user interface for managing menus including creating new menus reordering menu links and disabling links provided by modules it also provides the ability for links to content items to be added to menus while editing if configured on the content type the core custom menu links module provides the ability to add custom links to menus each menu can be displayed by placing a block in a theme region some themes also can display a menu outside of the block system see the related topics listed below for specific tasks recursos adicionales concept menu drupal user guide  ', 0),
(18, 'es', 'help_search', ' optimizing site performance what is site performance  site performance in this context refers to speed factors such as the page load time and the response time after a user action on a page what is caching  caching is saving alreadyrendered html output and other calculated data for later use the first time it is needed this saves time because the next time the same data is needed it can be quickly retrieved instead of recalculated automatic caching systems also include mechanisms to delete cached calculations or mark them as no longer valid when the underlying data changes to facilitate that cached data has a lifetime  which is the maximum time before the data will be deleted from the cache forcing recalculation  what is file aggregation  aggregation is when css and javascript files are merged together and compressed into a format that is much smaller than the original this allows for faster transmission and faster rendering on the other end what can i do to improve my site s performance  the following core software modules and mechanisms can improve your site s performance internal page cache module caches pages requested by users who are not logged in anonymous users do not use if your site needs to send different output to different anonymous users internal dynamic page cache module caches data for both authenticated and anonymous users with noncacheable data in the page converted to placeholders and calculated when the page is requested modulo big pipe changes the way pages are sent to users so that cacheable parts are sent out first with placeholders and the uncacheable or personalized parts of the page are streamed afterwards this allows the browser to render the bulk of the page quickly and fill in the details later performance page settings in the manage administrative menu if you navigate to configuration   development   performance  you will find a setting for the maximum cache lifetime as well as the ability to turn on css and javascript file aggregation recursos adicionales documentacion online para el modulo internal page cache documentacion online para el modulo internal dynamic page cache documentacion online para el modulo bigpipe ', 0),
(19, 'es', 'help_search', ' making your site secure  que son las actualizaciones de seguridad  cualquier software ocasionalmente tiene errores y a veces estos errores tienen implicaciones de seguridad cuando los errores de seguridad se corrigen en el nucleo los modulos o los temas que utiliza su sitio se lanzan en una actualizacion de seguridad  debera aplicar actualizaciones de seguridad para mantener su sitio seguro  que son los avisos de seguridad  un aviso de seguridad es un anuncio publico sobre un problema de seguridad informado en el software del nucleo los proyectos contribuidos con un icono de escudo y lanzamientos estables para este proyecto estan cubiertos por la politica de aviso de seguridad en su pagina de proyecto tambien estan cubiertos por la politica de aviso de seguridad de drupal los avisos de seguridad son administrados por el drupal security team  tareas de seguridad para mantener la seguridad de su sitio web es fundamental llevar un seguimiento de las actualizaciones actualizar el software de nucleo y los modulos y o temas de terceros consulte los temas relacionados que se enumeran a continuacion para saber cuales son las tareas especificas recursos adicionales security and maintenance drupal user guide  proceso de asesoramiento de seguridad y politica de permisos ', 0),
(20, 'es', 'help_search', ' usar la edicion de ajustes en linea quick  objetivo editar los ajustes en el lugar  que es la edicion rapida  el modulo principal de la bandeja de ajustes ofrece la posibilidad de editar rapidamente los ajustes en linea requiere el modulo central de enlaces contextuales para exponer los enlaces que le permiten editar en el lugar  quien puede editar los ajustes en el lugar  para seguir estos pasos para editar la configuracion en el lugar el modulo central de la bandeja de configuracion debe estar instalado ademas debe instalarse el modulo principal de la barra de herramientas o un sustituto aportado necesitaras tener el permiso de utilizar enlaces contextuales  asi como el permiso para editar el contenido particular o la configuracion pasos busque y visite una pagina en su sitio que tenga la configuracion que le gustaria editar click the contextual links edit button on the toolbar in most themes it looks like a pencil contextual edit links with the same icon will appear all over your page encuentre el enlace contextual para la parte de la pagina que desea editar por ejemplo si desea editar la configuracion para un bloque el enlace debe estar en la esquina superior derecha del bloque o la parte superior izquierda para los idiomas de derecha a izquierda haga clic en el enlace para abrir el menu de enlaces contextuales y haga clic en edicion rapida  en la pagina deberia aparecer un formulario de edicion de los ajustes haga sus ediciones y envie el formulario  ', 0),
(21, 'es', 'help_search', ' tracking the content of your website tracking overview the core history module tracks how recently users have viewed content items and provides a views field and filter that can be used to show users content that they haven t yet seen si usted tiene uno o mas modulos de seguimiento instalados en su sitio consulte los temas relacionados que se listan a continuacion para conocer las tareas especificas  ', 0),
(22, 'es', 'help_search', ' trabajar con idiomas y traducciones  que texto se puede traducir en su sitio  hay tres tipos de texto que se pueden traducir el contenido bloques elementos de contenido etc puede estar escrito en ingles o en otro idioma y puede traducirse a otros idiomas consulte managing content structure para saber mas sobre el contenido muchos elementos de configuracion tambien incluyen texto que puede ser traducido la configuracion por defecto proporcionada por el software de su sitio se proporciona en ingles tambien puede descargar traducciones proporcionadas por la comunidad consulte el tema managing and deploying configuration para obtener mas informacion sobre la configuracion user interface text that is provided by the core software your install profile themes and modules is provided in english but can be translated into other languages you can also download translations that communitymembers have provided working with languages overview the core language module lets you add new languages to your site provides the language switcher block and provides the ability to configure block visibility by language the block and block visibility settings are only available if you have multiple languages configured the core content translation configuration translation and interface translation modules let you translate content configuration and the builtin user interface respectively the core update manager module manages automatic downloads of communityprovided translations of default configuration and userinterface text see the related topics listed below for specific tasks  ', 0),
(23, 'es', 'help_search', ' accessibility of the administrative interface resumen de accesibilidad the core administrative interface has builtin compliance with many accessibility standards so that most pages are accessible to most users in their default state however certain pages become more accessible to some users through the use of a nondefault or improved interface these interfaces include desactivando la funcionalidad de arrastrar y soltar la interfaz de usuario predeterminada de arrastrar y soltar para ordenar tablas en la interfaz administrativa es dificil de utilizar para algunos usuarios como aquellos que solo usan el teclado y los que emplean lectores de pantalla y otras tecnologias de apoyo la interfaz de arrastrar y soltar se puede desactivar en una tabla haciendo clic en un enlace etiquetado mostrar pesos de fila sobre la tabla la interfaz alternativa permite a los usuarios ordenar la tabla eligiendo pesos numericos con numeros crecientes en lugar de arrastrar las filas de la tabla habilitar errores de formulario en linea errors that occur when you submit a form such as not filling in a required field are sometimes difficult for users to understand and locate in order to make these errors easier to find the best practice is to put a summary of the errors at the top of the form page to make them easier to understand the best practice is to display error messages with the form fields they are related to both of these practices are implemented by the core inline form errors module  ', 0),
(24, 'es', 'help_search', ' using the administrative interface  que componentes de la interfaz administrativa estan disponibles  the following administrative interface components are provided by the core software and its modules some contributed modules offer additional functionality funciones de accesibilidad para que todos los usuarios puedan realizar tareas administrativas consulte accessibility of the administrative interface para obtener mas informacion un sistema de menus por el que puede navegar para encontrar paginas para tareas administrativas el modulo basico barra de herramientas muestra este menu en la parte superior o izquierda de la pagina a la derecha en los idiomas de derecha a izquierda tambien hay modulos de terceros que presentan caracteristicas adicionales que pueden sustituir al modulo basico barra de herramientas como el modulo modulo barra de herramientas administrativa  el modulo principal shortcuts mejora la barra de herramientas con una lista configurable de enlaces a tareas de uso comun si instala el modulo principal contextual links las paginas no administrativas contendran enlaces que conducen a tareas administrativas relacionadas en su sitio o quick  la edicion en el lugar de la configuracion es proporcionada por el modulo central de la bandeja de ajustes consulte usar la edicion de ajustes en linea quick para obtener mas informacion el modulo principal help muestra temas de ayuda y proporciona un bloque de ayuda que se puede colocar en paginas administrativas para proporcionar una descripcion general de su funcionalidad  cuales son las secciones del menu administrativo  the administrative menu which you can navigate by visiting  admin on your site or by using an administrative toolbar has the following sections some may not be available depending on which modules are currently installed on your site and your permissions  content  find manage and create new pages manage comments and files structure  place and edit blocks set up content types and fields configure menus administer taxonomy and configure some contributed modules appearance  switch between themes install themes and update existing themes extend  update install and uninstall modules configuracion  configure la configuracion para diversas funcionalidades del sitio incluidos algunos modulos contribuidos people  manage user accounts and permissions reports  display information about site security necessary updates and site activity help  get help on using the administrative interface descripcion general de la interfaz de administracion install the core modules mentioned above to use the corresponding aspect of the administrative interface see the related topics listed below for more details on some aspects of the administrative interface  ', 0),
(25, 'es', 'help_search', ' habilitando servicios web  que es un servicio web  a web service allows your site to provide its content and data to other web sites and applications typically the data is transported via http in a serialized machinereadable format  que es la serializacion  serialization is the process of converting complex data structures into text strings so that they can be exchanged and stored the reverse process is called deserialization  json and xml are the two mostcommonlyused data serialization formats for web services  que es la autenticacion basica http  http basic authentication is a method for authenticating requests by sending a user name and password along with the request  que modulos proporcionan servicios web  the following core software modules provide web services json api module exposes entities to other applications using a fully compliant implementation of the json api specification  see managing content structure for more information on content entities and fields modulo de servicios web restful expone entidades y otros recursos a otras aplicaciones utilizando una implementacion rest  los datos se intercambian utilizando un formato de serializacion como json y se transfieren utilizando un metodo de autenticacion como http basic authentication serialization module provides a framework for adding specific serialization formats for other modules to use http basic authentication module provides a way for web services to be authenticated using http basic authentication against site user accounts there are also contributed modules that provide web services recursos adicionales online documentation for the restful web services module online documentation for the json api module comparison of the restful web services and json api modules ', 0),
(26, 'es', 'help_search', ' configurar busqueda de ayuda objetivo configure su sitio para que los usuarios puedan buscar ayuda pasos in the manage administrative menu navigate to ampliar  verify that the search help and block modules are installed or install them if they are not already installed en el menu administrativo administrar  dirigete a configuracion  gt  busqueda y metadatos  gt  paginas de busqueda  verifica que haya una pagina de busqueda de ayuda en la seccion paginas de busqueda  de lo contrario agrega una nueva pagina de tipo ayuda  compruebe el estado de indexacion de la pagina de busqueda de la ayuda si no esta totalmente indexada consulte el tema running and configuring cron sobre como ejecutar cron hasta que se complete la indexacion in the future you can click rebuild search index on this page or borrar la cache del sitio in order to force help topic text to be reindexed for searching this should be done whenever a module theme language or string translation is updated in the manage administrative menu navigate to structure   block layout  haz clic en el enlace de tu tema administrativo como el tema claro principal cerca de la parte superior de la pagina y verifica que ya haya un bloque de busqueda de ayuda ubicado en la region de ayuda si no es asi sigue los pasos en el tema relacionado para colocar el bloque formulario de busqueda en la region de ayuda al configurar el bloque elige ayuda como la pagina de busqueda y en la pestana paginas dentro de visibilidad  ingresa  admin help para hacer que el formulario de busqueda solo sea visible en la pagina principal de ayuda  en el menu administrativo administrar  vaya a ayuda  verifique que el bloque de busqueda este visible e intente realizar una busqueda  ', 0),
(27, 'es', 'help_search', ' working with help topics what is a help topic  a help topic describes a concept or steps to accomplish a task related to a feature provided by one or more modules or themes if the core search module is enabled these topics are also searchable where are help topics listed  the toplevel help topics are listed at ayuda links to other topics including nontoplevel help topics can be found under the related heading when viewing a topic page how are help topics provided  modules and themes can provide help topics as twigfilebased plugins in a project subdirectory called helptopics  plugin metadata is provided in yaml front matter within each twig file pluginbased help topics provided by modules and themes will automatically be updated when a module or theme is updated use the plugins in core modules help helptopics as a guide when writing and formatting a help topic plugin for your theme or module how are help topics translated  the title and body text of help topics provided by contributed modules and themes are translatable using traduccion de la interfaz de usuario provided by interface translation module topics provided by custom modules and themes are also translatable if they have been viewed at least once in a nonenglish language which triggers putting their translatable text into the translation database how can users search for help topics  to enable users to search help including help topics you will need to install the core search module configure a search page and add a search block to the help page or another administrative page a search page is provided automatically and if you use the core claro administrative theme a help search block is shown on the main help page then users with search permissions and permission to view help will be able to search help see the related topic configurar busqueda de ayuda for stepbystep instructions recursos adicionales help topics standards ', 0),
(28, 'es', 'help_search', ' configurando las paginas de busqueda objetivo configure una o mas paginas de busqueda pasos en el menu administrativo administrar  vaya a configuracion   busqueda y metadatos   buscar paginas  scroll down to the search pages section you will see a list of the alreadyconfigured search pages on your site to configure an existing search page click edit  or to add a new search page select the search page type and click add search page  enter the desired label name and url path for the search page for content search pages select the desired level of influence in ranking search results of the available content ranking factors click save  you will be returned to the search pages page verify that the correct search page is listed as default in the status column if not click set as default in the operations list for the correct search page opcionalmente deshabilite o elimine las paginas de busqueda que no desee tener disponibles en el sitio deshabilitar es temporal mientras que eliminar es permanente follow the steps in administrando el indice de busqueda to make sure that the search index is updated  ', 0),
(29, 'es', 'help_search', ' administrando el indice de busqueda objetivo manage the search index and make sure that the site is fully indexed for searching what is the search index  los tipos de busqueda de contenido y ayuda proporcionados por el software central preindexan su contenido y almacenan los resultados en varias tablas de bases de datos que se denominan colectivamente indice de busqueda  el proceso de indexacion representa el contenido y lo divide en palabras que luego se pueden relacionar de manera mas eficiente con consultas de palabras clave cuando los usuarios realizan busquedas la indexacion de busqueda ocurre durante las ejecuciones de cron consulte running and configuring cron para obtener mas informacion sobre cron pasos en el menu administrativo administrar  vaya a configuracion   busqueda y metadatos   buscar paginas  under indexing throttle  select the number of items to index per cron run  a smaller number will make cron faster and reduce the possibility of timeout a larger number will make sure more of your site is indexed in fewer cron runs under default indexing settings  enter the desired minimum word length to index  words smaller than this length will be dropped from both keywords when searching and content when indexing si su web utiliza idiomas como el chino japones o coreano puede marcar adicionalmente manejo de simple cjk bajo configuraciones de indexado por defecto para proporcionar apoyo a estos idiomas click save configuration  and you should be returned to the search pages page click reindex site if you have changed the indexing configuration or later on if you believe that the search index has been corrupted siga los pasos de running and configuring cron para asegurarse de que se ha configurado una tarea cron after waiting for cron to run several times verify that the content has been fully indexed for searching the overall status is listed under indexing progress  and the status for each search page is shown in the indexing progress column of the search pages section  ', 0);
INSERT INTO `search_dataset` (`sid`, `langcode`, `type`, `data`, `reindex`) VALUES
(30, 'es', 'help_search', ' configuracion de la busqueda del sitio what are search pages  the core search module organizes site search into pages  each page allows users to search a particular type of content with a particular configuration the configuration includes specifying a url that starts with search  a name for the page and additional options for some search page types when users visit the main search page see buscar  they will see the configured search pages that they have access to each search page has a search form on it and the page will display search results after the user enters keywords into the form and clicks the search button what modules provide site search  the core search module provides the ability to configure search pages search page types are provided by both core and contributed modules the core modules that provide search page types are the node module for searching content pages the user module for searching user profiles the help module for searching help topics as an alternative to the core search module s system of search pages you can use contributed modules to provide site search for example the apache solr and sphinx contributed modules use thirdparty technology to provide site search what are the limitations of the core search module  there are two main limitations of the core search module first it is not appropriate for very large sites if you have a large site look into other search technologies like apache solr second the node search page type only supports exact keyword matching which is not the behavior that most users will expect you can improve this by installing a languagespecific stemming module for your language such as porter stemmer for american english which makes it so that for example a search for the word walk would match pages containing the words walk walking and walked what are the search permissions  los usuarios con el permiso utilizar busqueda pueden utilizar el bloque formulario de busqueda y la pagina busqueda  este permiso es necesario para cualquier busqueda configurada en el modulo de busqueda principal in addition to use search   view user information permission is needed for searching users in addition to use search   view published content permission is needed for searching content users with use advanced search permission can use more complex search filtering when performing content searches configuring site search overview para configurar la busqueda en el sitio con el modulo principal de busqueda debera configurar una o mas paginas de busqueda tambien debera verificar o modificar los permisos para que los roles de usuario deseados puedan buscar en el sitio consulte administrar cuentas de usuario y visitantes del sitio para obtener mas informacion sobre roles y permisos para la busqueda de contenido tambien debera asegurarse de que el indice de busqueda este configurado y que el sitio este completamente indexado por ultimo es posible que desee colocar el bloque formulario de busqueda en las paginas de su sitio o agregar la pagina de busqueda a un menu de navegacion para que los usuarios puedan acceder facilmente a la busqueda consulte los temas relacionados que se enumeran a continuacion para tareas especificas recursos adicionales online documentation for the search module ', 0),
(31, 'es', 'help_search', ' borrar la cache del sitio objetivo clear the data in the site cache  que es la cache  some of the calculations that are done when your site loads a page take a long time to run to save time when these calculations would need to be done again their results can be cached in your site s database there are internal mechanisms to clear cached data when the conditions or assumptions that went into the calculation have changed but you can also clear cached data manually when your site is misbehaving a good first step is to clear the cache and see if the problem goes away pasos in the manage administrative menu navigate to configuration   development   rendimiento  haz clic en limpiar todas las caches  se borraran los datos almacenados en cache de tu sitio recursos adicionales concept cache drupal user guide  ', 0),
(32, 'es', 'help_search', ' cambiar la configuracion basica del sitio objetivo configure los ajustes basicos de su sitio incluido el nombre del sitio el eslogan la direccion de correo electronico principal la zona horaria predeterminada el pais predeterminado y los formatos de fecha que se utilizaran pasos in the manage administrative menu navigate to configuration   system   configuraciones basicas del sitio  introduce el nombre del sitio web eslogan y una direccion de email principal para tu sitio web haga clic en guardar configuracion  deberia aparecer un mensaje indicando que se han guardado las configuraciones in the manage administrative menu navigate to configuration   region and language   opciones regionales  seleccione el pais y la zona horaria predeterminados para su sitio haga clic en guardar configuracion  deberia aparecer un mensaje indicando que se han guardado las configuraciones in the manage administrative menu navigate to configuration   region and language   formato de fecha y hora  examine los patrones de los formatos de fecha predeterminados largo medio y corto si alguno de ellos no coincide con los formatos de fecha que desea utilizar en su sitio web pulse editar en esa fila para editar el formato que desee cambiar modifique la cadena de formato hasta que el formato mostrado se ajuste a lo que desea las cadenas de formato de fecha se componen de codigos de formato de fecha php haga clic en guardar formato  deberia aparecer un mensaje indicando que se ha guardado el formato repita los tres pasos anteriores para realizar cualquier otro cambio en el formato de fecha recursos adicionales php date format codes reference ', 0),
(33, 'es', 'help_search', ' configuracion de respuestas a un error incluidas las paginas 403404 objetivo configura tu sitio para responder adecuadamente a los errores del sitio incluidas las respuestas de paginas 403 y 404  que son las respuestas 403 y 404  when a user visits a web page the web server sends a response code in addition to the page content a normal nonerror response has code 200 if the page does not exist on the site the response code is 404 if the page exists but the user is not authorized to visit the page the response code is 403 the core software provides default responses for both 403 and 404 codes but if you prefer you can create your own pages for each  que otros errores pueden ocurrir  under some situations your site can generate error messages these can be due to user errors such as entering invalid values in a form or incorrect configuration php runtime errors or software bugs some errors may result in a white screen of death  a totally blank web page response less drastic errors will generate error messages you can configure what happens when an error message is generated pasos si lo desea cree paginas para las respuestas 403 y 404 indique las direcciones url de estas paginas in the manage administrative menu navigate to configuration   system   configuraciones basicas del sitio  in the error pages section enter the url for your 403404 pages starting after the site home page url for example if your site url is https examplecom and your 404 page is https examplecom notfound  you would enter  notfound  haga clic en guardar configuracion  deberia aparecer un mensaje indicando que se han guardado las configuraciones in the manage administrative menu navigate to configuration   development   registro y errores  for a production site select none under error messages to display  for a site that is in development select one of the other options so that you are more aware of the errors the site is generating haga clic en guardar configuracion  deberia aparecer un mensaje indicando que se han guardado las configuraciones  ', 0),
(34, 'es', 'help_search', ' habilitar y deshabilitar el modo de mantenimiento objetivo put your site in maintenance mode to perform maintenance operations and then return to normal mode when finished  que es el modo de mantenimiento  when your site is in maintenance mode most site visitors will see a simple maintenance mode message page rather than being able to use the full functionality of the site users with use the site in maintenance mode permission who are already logged in will be able to use the full site and the log in page at  user will also be accessible to anyone pasos in the manage administrative menu navigate to configuration   development   modo de mantenimiento  check put site into maintenance mode  optionally change the message to display when in maintenance mode  and click save configuration  your site will be in maintenance mode perform your maintenance operations in the manage administrative menu navigate to configuration   development   modo de mantenimiento  uncheck put site into maintenance mode and click save configuration  your site will be back in normal operation mode borrar la cache del sitio consulte borrar la cache del sitio para obtener instrucciones  ', 0),
(35, 'es', 'help_search', ' instalar un modulo objetivo install a core module or a contributed module that has already been downloaded pasos in the manage administrative menu navigate to ampliar  enter a word from the module name or description into the filter box to make the list of modules smaller locate the module you want to install check the box next to the name of the module you want to install you can also check more than one box to install multiple modules at the same time if the checkbox is disabled for the module you are trying to install expand the information to see why you may need to download an additional module that your module requires click install at the bottom of the page if you chose to install a module with dependencies that were not already installed or if you chose an experimental module confirm your choice on the next page wait for the module or modules to be installed you should be returned to the extend page with a message saying the module or modules were installed  ', 0),
(36, 'es', 'help_search', ' desinstalar un modulo objetivo desinstalar un modulo su sitio debe estar en modo de mantenimiento cuando desinstale modulos consulte habilitar y deshabilitar el modo de mantenimiento para obtener mas detalles pasos in the manage administrative menu navigate to extend   desinstalar  enter a word from the module name or description into the filter box to make the list of modules smaller locate the module you want to uninstall in the description column see if there are reasons that this module cannot be uninstalled for example you may have created content using this module which you would need to delete first or there may be another module installed that requires this module to be installed you would need to uninstall the other module first if there are no reasons listed the module can be uninstalled check the box in the uninstall column next to the module s name click uninstall at the bottom of the page verify the list of modules to be uninstalled and configuration to be deleted on the confirmation page and click uninstall  wait for the module to be uninstalled you should be returned to the uninstall page with a message saying the module was uninstalled  ', 0),
(37, 'es', 'help_search', ' running reports on your site objetivo run reports to learn about the status and health of your site pasos in the manage administrative menu navigate to reports   informe de estado to see a report that summarizes the health and status of your site if there are any warnings or errors you will need to fix them take note of any upcoming highly critical security releases that may impact your site if you have the core database logging module installed in the manage administrative menu navigate to reports   recent log messages to see a report of the error and informational messages your site has generated you can filter the report by severity to see only the most critical messages if desired if you have the core update manager module installed in the manage administrative menu navigate to reports   available updates to see a report of the updates that are available for your site software if last checked is far in the past click check manually to update the report scan the report if the core software or any modules or themes have security updates available you should update them as soon as possible recursos adicionales security and maintenance drupal user guide   which includes information on how to update your site s core software modules and themes  ', 0),
(38, 'es', 'help_search', ' instalacion de un tema y configuracion de temas predeterminados objetivo instale un tema principal o un tema contribuido que ya se haya descargado elija los temas predeterminados para usar en el sitio y en las paginas administrativas pasos in the manage administrative menu navigate to apariencia  busque los temas que desea utilizar como tema predeterminado del sitio para las paginas administrativas for each of these themes if the theme is in the uninstalled themes section click the install link to install the theme wait for the theme to be installed translations might be downloaded you should be returned to the appearance page locate the theme that you want to be your default theme which should now be in the installed themes section if it is not already labeled as the default theme  click the set as default link en la parte inferior de la pagina seleccione el tema de administracion que desea utilizar en las paginas administrativas haga clic en guardar configuracion si selecciono un nuevo tema si cambio el tema predeterminado para su sitio visite la pagina de inicio del sitio u otra pagina en la parte no administrativa de su sitio y verifique que el sitio este usando el nuevo tema si cambio el tema de administracion verifique que el nuevo tema se este utilizando en las paginas administrativas  ', 0),
(39, 'es', 'help_search', ' desinstalar un tema no utilizado objetivo desinstale un tema que se instalo anteriormente pero que ya no se usa en el sitio pasos in the manage administrative menu navigate to apariencia  localice el tema que desea desinstalar en la seccion temas instalados  haga clic en el enlace desinstalar para desinstalar el tema si no hay un enlace desinstalar  el tema no se puede desinstalar porque se esta utilizando como tema predeterminado del sitio como tema de administracion o es el tema base para otro tema instalado  ', 0),
(40, 'es', 'help_search', ' creando una cuenta de usuario objetivo crear una nueva cuenta de usuario pasos in the manage administrative menu navigate to usuarios  click add user  enter the email address   username  and password  twice for the new user verify that the roles checked for the new user are correct if you want the new user to receive an email message notifying them of the new account check notify user of new account  optionally change other settings on the form haga click en crear una nueva cuenta  you will be left on the add user page repeat these steps if you have more user accounts to create  ', 0),
(41, 'es', 'help_search', ' anadiendo un nuevo rol objetivo create a new role pasos in the manage administrative menu navigate to people   roles  click add role  enter the desired role name  if desired click edit to change the machine name for the role click save  you should be returned to the roles page and your new role should be in the role list  ', 0),
(42, 'es', 'help_search', ' administrar cuentas de usuario y visitantes del sitio what is a user  a user is anyone accessing or viewing your site anonymous users are users who are not logged in and authenticated users are users who are logged in what is a role  roles are used to group and classify users each user can be assigned one or more roles there are also special roles for all anonymous and all authenticated users what is a permission  granting a permission to a role allows users who have been assigned that role to perform an action on the site such as viewing content editing or creating a particular type of content administering settings for a particular module or using a particular function of the site such as search  overview of managing user accounts and visitors the core user module allows users to register log in and log out and administrators to manage user roles and permissions the core ban module allows administrators to ban certain ip addresses from accessing the site depending on which modules you have installed on your site the related topics below will help you with tasks related to managing user accounts and visitors  ', 0),
(43, 'es', 'help_search', ' modificar los permisos de un rol objetivo modify the permissions for an existing role pasos in the manage administrative menu navigate to people   permisos  review the permissions for the role paying particular attention to the permissions marked with warning give to trusted roles only this permission has security implications uncheck permissions that this role should not have in the row of the permission and the column of the role check permissions that this role should have clique guardar permisos   ', 0),
(44, 'es', 'help_search', ' configurar como se crean y eliminan las cuentas de usuario objetivo configure los ajustes relacionados con como se crean y eliminan las cuentas de usuario  cuales son los ajustes relacionados con la creacion y eliminacion de cuentas de usuario  you can make it possible for new users to register themselves for accounts with or without email verification or administrative approval or you can make it so only administrators with administer users permission can register new users you can configure what happens to content that a user created if their account is canceled  deleted puede editar los mensajes de correo electronico que se envian a los usuarios cuando sus cuentas estan pendientes aprobadas creadas bloqueadas o canceladas o cuando solicitan un restablecimiento de contrasena what are variables in email message text  variables are short text strings enclosed in square brackets that you can insert into configured email message text when an individual message is generated data from your site is substituted for the variables some commonlyused variables are site name the name of your website site url the url of your website site loginurl la url donde los usuarios inician sesion en su sitio user displayname el nombre de usuario que se muestra usuario accountname el nombre de la cuenta del usuario user mail the user s email alias user onetimeloginurl an expiring url that a user can use to log in once if they need to reset their password pasos in the manage administrative menu navigate to configuration   people   configuracion de la cuenta  select the method you want to use for creating user accounts and check or uncheck the box that requires email verification to match the settings you want for your site select the desired option for what happens to content that a user created if their account is canceled optionally edit the text of email messages related to user accounts verifique que las demas configuraciones sean correctas haga clic en guardar configuracion  deberia aparecer un mensaje indicando que se han guardado las configuraciones  ', 0),
(45, 'es', 'help_search', ' modificar o eliminar una cuenta de usuario objetivo update or delete an existing user account pasos in the manage administrative menu navigate to usuarios  enter all or part of the user name or email address of the user account you want to update or delete and click filter  a short list of user accounts including the account of interest should be shown in the table if not modify the filter text until you can find the account of interest click edit in the operations area of the account of interest to delete the user account scroll to the bottom and click cancel account  select what you want to happen to the user s content on the next screen and click cancel account  to update the user account enter new values in the form and click save   ', 0),
(46, 'es', 'help_search', ' viewing drupal announcements what are drupal announcements  a feed of announcements about the drupal project and drupal association programs the purpose of this feed is to provide a channel for outreach directly to drupal site owners this content must be highly relevant to site owners interests serve the strategic goals of the project and or promote the sustainability of the project and the drupal association the module sources its content from a json feed generated from here  the governance policy for the content is documented here  how can i see the announcements in my site  if you have the toolbar module enabled you will see a direct link to them in the toolbar if the toolbar module is not enabled the content can always be accessed in the anuncios page who can see the announcements  users with the view official announcements related to drupal permission can view drupal announcements recursos adicionales announcement module overview ', 0),
(47, 'es', 'help_search', ' configurar un bloque previamente colocado objetivo configurar los ajustes de un bloque ya situado en una seccion de un tema pasos en el menu administrativo administrar  vaya a estructura   diseno de bloques  haga clic en el nombre del tema que contiene el bloque opcionalmente haga clic en demostrar regiones de bloque para ver las regiones del tema si solo desea cambiar la region donde se encuentra un bloque o el orden de los bloques dentro de una region arrastre los bloques a sus posiciones deseadas y haga clic en guardar bloques  si desea cambiar configuraciones adicionales busque la region donde se encuentra actualmente el bloque que desea actualizar y haga clic en configurar en la linea de la descripcion del bloque edite la configuracion del bloque la configuracion disponible varia segun el modulo que proporciona el bloque pero para todos los bloques puede cambiar  titulo del bloque  la cabecera del bloque en tu sitio para algunos bloques necesitara marcar la casilla de verificacion sobrescribir titulo para poder introducir un titulo mostrar titulo  marque la casilla si desea que se muestre el titulo visibilidad  agregue condiciones para cuando se debe mostrar el bloque region  cambie la region del tema en la que se muestra el bloque click save block   ', 0),
(48, 'es', 'help_search', ' gestionar bloques  que son los bloques  los bloques son cajas de contenido representados en un area o region de una pagina web de su sitio los bloques se colocan y configuran especificamente para cada tema what are content blocks  content blocks are blocks whose content you can edit you can define one or more block types  and attach fields to each block type content blocks can be placed just like blocks provided by other modules  que es la descripcion del bloque  la descripcion del bloque es un nombre de identificacion para un bloque que se muestra en la interfaz administrativa no se muestra en el sitio  que es el titulo del bloque  el titulo del bloque es el encabezado que se muestra opcionalmente a los visitantes del sitio cuando el bloque se coloca en una region overview for managing blocks the block module allows you to place blocks in regions of your installed themes and configure block settings the block content module allows you to manage block types and content blocks see the related topics listed below for specific tasks recursos adicionales blocks drupal user guide  ', 0),
(49, 'es', 'help_search', ' colocando un bloque objetivo coloque un bloque en la region de un tema pasos in the manage administrative menu navigate to structure  diseno de bloques haga clic en el nombre del tema en el que desea colocar el bloque opcionalmente haga clic en demostrar regiones de bloque para ver las regiones del tema busque la region donde desea colocar el bloque y haga clic en el colocar bloque de esa region aparecera un cuadro de dialogo modal busque el bloque que desea colocar y haga clic en colocar bloque  aparecera un cuadro de dialogo modal configurar bloque  configure el bloque y haga clic en guardar bloque  consulte configurar un bloque previamente colocado para obtener detalles de configuracion  ', 0),
(50, 'es', 'help_search', ' gestion de filtros de texto y formatos de texto objetivo configure text formats on the site what are text filters and text formats  a text filter is a processing step that can be applied to text either to transform it in some way such as converting urls in the text into html links or to defend against potentiallydangerous input from site users a text format is an ordered sequence of text filters text filters are provided by modules text formats are managed by the core filter module text fields that have formatted in the field type name such as text formatted   use text formats users choose the text format when editing the field text when the field text is shown on the site it is processed by the chosen text format administrators can configure text formats and assign permissions for who can use each format if the core text editor module is enabled administrators can also associate visual editors with text formats what text filters are available  some of the more commonly used text filters are limit allowed html tags and correct faulty html limits which html tags can be used useful both for site security and enforcing site design convertir saltos de linea en html line breaks in html source are displayed as horizontal spaces this filter converts line breaks into html paragraph and line break tags convertir las url en enlaces takes plain urls in text and turns them into html links restringir imagenes a este sitio for text formats that allow html image tags restricts images to urls within this site pasos en el menu administrativo administrar  vaya a configuracion   autoria de contenido   formato y editores de texto  si no tiene instalado el modulo principal text editor el enlace del menu y el titulo de la pagina seran formatos de texto  click configure to configure an existing text format or  add text format to create a new text format enter the desired name for the text format check the roles that can use this text format some html tags allow users to embed malicious links or scripts in text to ensure security anonymous and untrusted users should only have access to text formats that restrict them to either plain text or a safe set of html tags improper text format configuration is a security risk if the core text editor module is installed see the related topic to connect a text editor to this text format under enabled filters  check the text filters that you want to use under filter processing order  drag the filters to the correct order choose the order carefully for example if you have a filter that results in a particular html tag being added to the text that should run after a filter that restricts html tags to avoid deleting the new tags the first filter added under filter settings  verify and adjust the settings for each active filter that has configuration options click save configuration  which will return you to the text formats and editors page repeat these steps if you have additional text formats to configure  ', 0),
(51, 'es', 'help_search', ' creating a content block objetivo create a content block which can later be placed on the site pasos in the manage administrative menu navigate to content  open the content blocks tab click add content block  if you have more than one block type defined on your site click the name of the type you want to create ingrese una descripcion de su bloque que se mostrara a los administradores y el texto del cuerpo de su bloque pulse guardar   ', 0),
(52, 'es', 'help_search', ' defining a block type objetivo define a block type and its fields pasos in the manage administrative menu navigate to structure   tipos de bloques  click add block type  introduzca una etiqueta para este tipo de bloque mostrado en la interfaz de administracion opcionalmente edite el nombre de sistema generado automaticamente o la descripcion pulse guardar  sera redirigido de nuevo a la pagina de tipos de bloque  haga clic en administrar campos en la fila de su nuevo tipo de bloque y agregue los campos deseados a su tipo de bloque si lo desea haga clic en gestionar la visualizacion del formulario o en gestionar la visualizacion para modificar la visualizacion del formulario de edicion o la de los campos del tipo de bloque  ', 0),
(53, 'es', 'help_search', ' creacion de un elemento de contenido objetivo crear y publicar un elemento de contenido consulte administrando contenido para obtener mas informacion sobre los tipos de contenido y los elementos de contenido  quien puede crear contenido  users with the acceder a la pagina de resumen de contenido permission can visit the content page as described in this topic each content type has its own create permissions for example to create content of type article a user would need the article create new content permission in addition users with the bypass content access control or administer content permission can create content items of all types some contributed modules change the permission structure for creating content pasos en el menu administrativo administrar  navegue hasta contenido  haz clic en anadir contenido  si hay mas de un tipo de contenido definido en su sitio que tiene permiso para crear haga clic en el nombre del tipo de contenido que desea crear on the content edit form enter the title of your content which will show as the page title when the content item is displayed on a page and also as the label for the content item in administration screens complete los otros campos que se muestran en el formulario de edicion para este tipo de contenido especifico leave the published field checked to publish the content immediately or uncheck it to make it unpublished unpublished content is generally not shown to nonadministrative site users optionally click preview to preview the content click save  you will see the content displayed on a page recursos adicionales basic page management drupal user guide  creating a content item drupal user guide  ', 0),
(54, 'es', 'help_search', ' crear un tipo de contenido objetivo crear un nuevo tipo de contenido consulte administrando contenido para obtener mas informacion sobre los tipos de contenido  quien puede crear un tipo de contenido  users with the administrar tipos de contenido permission typically administrators can create new content types pasos en el menu administrativo administrar  vaya a estructura   tipos de contenido  haga clic en agregar tipo de contenido in the name field enter a name for the content type which is how it will be listed in the administrative interface optionally enter a description for the content type you may also want to adjust some of the settings in the vertical tabs section of the edit page click save and manage fields  your content type will be created and assuming you have the core field ui module installed you will be taken to the manage fields page for the content type if you do not have the core field ui module installed the button will say save instead if you have the core field ui module installed follow the steps in the related topics to add fields to the new content type set up the editing form and configure the display recursos adicionales adding a content type drupal user guide  setting up content structure drupal user guide  ', 0),
(55, 'es', 'help_search', ' editar un elemento de contenido objetivo find a content item and edit it or update a group of content items in bulk see administrando contenido for more about content types and content items  quien puede encontrar y editar contenido  los usuarios con la acceder a la pagina de resumen de contenido permiso pueden usar la pagina content para encontrar contenido cada tipo de contenido tiene sus propios permisos de edicion por ejemplo para editar el contenido del tipo de articulo un usuario necesitaria el articulo  editar el permiso de contenido propio para editar un articulo que creo o el articulo  editar cualquier contenido permiso para editar un articulo que alguien mas creo ademas los usuarios con el control de acceso de contenido de omision o administrar contenido pueden editar elementos de contenido de todos los tipos algunos modulos contribuidos cambian la estructura de permiso para editar contenido pasos en el menu administrativo administrar  navegue hasta contenido  opcionalmente use filtros para reducir la lista de elementos de contenido que se muestran  title  key word s from the title tipo de contenido estado publicado language si ingresa o selecciona valores de filtro haga clic en filtro para aplicar los filtros si lo desea puede ordenar la lista haciendo clic en la cabecera de una columna haga clic de nuevo para invertir el orden para editar el titulo u otros valores de campo para un elemento de contenido haga clic en editar en la fila del elemento de contenido actualice los valores y haga clic en guardar  algunos tipos de ediciones se pueden realizar de forma masiva en varios elementos de contenido por ejemplo para publicar varios elementos de contenido no publicados marque las casillas en la columna izquierda columna derecha en los idiomas de derecha a izquierda para seleccionar los elementos de contenido deseados para accion  seleccione la accion publicar contenido  haga clic en aplicar a elementos seleccionados para realizar el cambio las otras acciones bajo accion funcionan de manera similar recursos adicionales basic page management drupal user guide  editing a content item drupal user guide  ', 0),
(56, 'es', 'help_search', ' administrando contenido  que es un elemento de contenido  a content item is a type of content entity for pagelevel content which can have fields that store text html markup images attached files and other data see managing content structure for more about content entities and fields  que es un tipo de contenido  los elementos de contenido se dividen en tipos de contenido  que son los subtipos de entidad para el tipo de entidad de elemento de contenido cada tipo de contenido tiene sus propios campos y ajustes de visualizacion por ejemplo puede configurar tipos de contenido para paginas articulos recetas eventos y entradas de blog en su sitio web overview of managing content el modulo central node le permite definir los tipos de contenido y anadir y editar elementos de contenido el modulo central field ui le permite adjuntar campos a cada tipo de contenido y gestionar el formulario de edicion y la visualizacion de cada tipo de contenido consulte los temas relacionados que se enumeran a continuacion para ver las tareas especificas muchos otros modulos principales y contribuidos y perfiles de instalacion proporcionan tipos de contenido predefinidos modifican la estructura de permisos para los elementos de contenido y proporcionan otras funcionalidades  ', 0),
(57, 'es', 'help_search', ' administrar puntos de interrupcion de alto ancho y resolucion  que son los puntos de ruptura  los puntos de ruptura son el punto en el que el contenido de su sitio respondera para proporcionar al usuario la mejor disposicion posible para consumir la informacion un punto de ruptura separa la altura o el ancho de los puntos de vista pantallas impresoras y otros tipos de salida de medios en tramos por ejemplo un punto de ruptura de ancho de 40em crea dos saltos uno para anchos de hasta 40em y otro para anchos superiores a 40em los puntos de ruptura pueden utilizarse para definir cuando los disenos deben pasar de un formulario a otro cuando deben cambiar el tamano de las imagenes y otros cambios que deben responder a los cambios en la altura o la anchura de la pantalla  que son las consultas de medios  media queries are a formal way to encode breakpoints for instance a width breakpoint at 40em would be written as the media query minwidth 40em breakpoints are really just media queries with some additional metadata such as a name and multiplier information  que son los multiplicadores de resolucion  los multiplicadores de resolucion son una medida de la resolucion de la ventana del dispositivo que se define como la relacion entre el tamano de pixel fisico del dispositivo activo y el pixel independiente del tamano de dispositivo  el modulo breakpoint define multiplicadores de 1 15 y 2 al definir puntos de interrupcion los modulos y los temas pueden definir que multiplicadores se aplican a cada punto de interrupcion  que es un grupo de puntos de ruptura  los saltos de pantalla breakpoints se pueden organizar en grupos los modulos y temas deberian usar los grupos para separarlos estos grupos se pueden usar para diferentes propositos como saltos de pantalla para distintas presentaciones o para redimensionar imagenes managing breakpoints and breakpoint groups overview el modulo breakpoint permite definir puntos de inflexion y grupos de puntos de inflexion en archivos yaml los modulos y temas pueden utilizar la api proporcionada por el modulo breakpoint para definir puntos de inflexion y grupos de puntos de inflexion y para asignar multiplicadores de resolucion a los puntos de inflexion recursos adicionales working with breakpoints in drupal estandares de la w3c para media queries ', 0),
(58, 'es', 'help_search', ' conectando editores de texto a formatos de texto objetivo configurar un formato de texto para que cuando un usuario este editando texto y seleccione este formato de texto se muestre un editor de texto instalado en su sitio configure el editor de texto por ejemplo eligiendo que botones y funciones estan disponibles ver gestion de filtros de texto y formatos de texto para mas informacion sobre los formatos de texto  que es un editor de texto  un editor de texto es un software normalmente una libreria de javascript que proporciona botones y otros mecanismos de comando para facilitar la edicion de texto html algunos editores se denominan editores visuales o wysiwyg lo que ves es lo que obtienes   estos editores ocultan los detalles de html del usuario y en su lugar muestran la salida formateada en la pantalla el modulo principal text editor proporciona un marco para implementar editores de texto en su sitio el modulo principal ckeditor 5 proporciona ckeditor 5 que es un editor de texto de javascript ampliamente utilizado que crea html limpio y valido el modulo tambien impone las restricciones de etiquetas html en el formato de texto asociado varios modulos contribuidos proporcionan otros editores para instalar un nuevo editor ademas de instalar el modulo es posible que deba descargar la libreria del editor desde un sitio de terceros pasos en el menu administrativo administrar  vaya a configuracion   autoria de contenido   formato y editores de texto  la columna editor de texto de la tabla muestra el editor de texto que esta conectado actualmente a cada formato de texto si lo hay siga los pasos del tema gestion de filtros de texto y formatos de texto para anadir un nuevo formato de texto o configurar un formato de texto existente cuando llegue al paso sobre los editores de texto vuelva a este tema seleccione ckeditor 5 como editor de texto u otro editor de texto que haya instalado el resto de estos pasos asumen que selecciono ckeditor 5  en configuracion de la barra de herramientas  arrastre los botones entre botones disponibles y barra de herramientas activa  solo se mostraran al usuario los botones de la barra de herramientas activa  al enfocar o pasar el mouse sobre un boton se mostrara una informacion sobre herramientas que explica lo que hace el boton arrastre los botones dentro de la barra de herramientas activa al orden deseado y agrupe los botones arrastrandolos entre los identificadores de grupo arrastre un nuevo identificador de grupo a la barra de herramientas para agregar grupos adicionales si agrega botones que requieren configuracion la seccion configuracion del complemento ckeditor 5 estara visible y proporcionara sus respectivos formularios de configuracion vuelva a gestion de filtros de texto y formatos de texto para completar la configuracion del formato de texto y asegurese de guardar el formato de texto  ', 0),
(59, 'es', 'help_search', ' configurar comentarios objetivo configure un tipo subtipo de entidad de contenido para permitir los comentarios utilizando un tipo de comentario que haya configurado consulte managing content structure para obtener mas informacion sobre las entidades y los campos de contenido y crear un tipo de comentario para configurar un tipo de comentario  quien puede configurar los comentarios  in order to follow these steps the field ui module must be installed you ll need the comment module s administer comments and comment settings permission in order to change comment settings for a comment field you ll also need to have the appropriate permission for adding fields to the entity type or subtype that the comments are attached to for example to add a comment field to content items provided by the node module you would need the node module s administer content types permission pasos siga los pasos del tema relacionado agregar un campo a un subtipo de entidad para agregar un campo de tipo comentarios al tipo o subtipo de entidad deseado en la primera pagina de configuracion de campo elija el tipo de comentario para usar con este tipo o subtipo de entidad tambien notara que el campo numero permitido de valores no se puede cambiar para los campos de comentarios en la siguiente pagina de configuracion de campos introduzca la configuracion deseada para el campo de comentarios  threading  whether or not the comments are collected by threads with people able to reply to particular comments instead of to the content entity itself comments per page  the maximum number of comments displayed on one page a pager will be added if you exceed this limit  anonymous commenting  whether or not anonymous commenters are allowed or required to leave contact information with their comments only applies if anonymous users have permission to post comments  mostrar formulario de respuesta en la misma pagina que los comentarios  si el formulario de respuesta de comentarios se muestra en la misma pagina que los comentarios si no se selecciona al hacer clic en responder se abrira una nueva pagina con el formulario de respuesta preview comments  whether previewing comments before submission is required   optional  or disabled  valor predeterminado  cada entidad individual tiene su propia configuracion de comentarios pero aqui puede establecer valores predeterminados para la configuracion de comentarios para este tipo de entidad o subtipo los valores de configuracion de comentarios son  abierto  se permiten comentarios cerrado  los comentarios anteriores permanecen visibles pero no se permiten nuevos comentarios oculto  se ocultan los comentarios anteriores y no se permiten nuevos comentarios recursos adicionales documentacion en linea para la configuracion de los comentarios de contenido ', 0),
(60, 'es', 'help_search', ' crear un tipo de comentario objetivo crea un nuevo tipo de comentario consulte gestion de comentarios para obtener informacion sobre los comentarios y los tipos de comentarios  quien puede crear un tipo de comentario  los usuarios con el permiso adminitra tipos de comentarios y sus opciones  normalmente administradores pueden crear tipos de comentarios pasos in the manage administrative menu navigate to structure   tipos de comentario  haga clic en agregar tipo de comentario  in the label field enter a name for the comment type which is how it will be listed in the administrative interface en el campo tipo de entidad objetivo  seleccione el tipo de entidad a comentar consulte managing content structure para obtener mas informacion sobre las entidades y los campos de contenido haga clic en guardar  se creara el tipo de comentario optionally if you have the core field ui module installed you can follow the steps in the related topics to add fields to the new comment type set up the editing form and configure the display  ', 0),
(61, 'es', 'help_search', ' disabling comments objetivo turn off commenting for a particular entity see managing content structure for more about content entities and fields note that if you want to turn off commenting for all entities of an entity type or subtype you will need to edit the field settings for the comment field see configurar comentarios for more about configuring the comment field  quien puede deshabilitar los comentarios  necesitara el permiso administer comments and comment settings para deshabilitar los comentarios tambien necesitara permiso para editar la entidad en la que se encuentran los comentarios pasos find the entity you want to disable comments for and edit it for example to turn off comments on a content item you could find it by navigating in the manage administrative menu to content  filtering to find the content item and clicking edit  en configuracion de comentario  seleccione la configuracion de comentarios deseada  abierto  se permiten comentarios cerrado  los comentarios anteriores permanecen visibles pero no se permiten nuevos comentarios oculto  se ocultan los comentarios anteriores y no se permiten nuevos comentarios salvar la entidad  ', 0),
(62, 'es', 'help_search', ' moderating comments objetivo decide que comentarios se muestran en el sitio web  quien puede moderar los comentarios  users with the administer comments and comment settings permission typically administrators can moderate comments you will also need the access the content overview page permission from the node module if it is installed to navigate to the comment management page pasos in the manage administrative menu navigate to content   comentarios  a list of all comments is shown to unpublish comments select one or more comments by checking the boxes on the left side right side in righttoleft languages then select unpublish comment from the action select list and click apply to selected items  if you select the delete comment action you can instead delete the unwanted comments to change the content of a comment click edit from the dropdown button for a particular comment to publish comments that are not yet visible on the website navigate to the comentarios sin aprobar tab select one or more comments by checking the boxes on the left side right side in righttoleft languages then select publish comment from the action select list and click apply to selected items  recursos adicionales documentacion en linea para moderar comentarios ', 0),
(63, 'es', 'help_search', ' gestion de comentarios  que es un comentario  a comment is a piece of content typically posted by a website visitor which provides discussion or commentary on other content like blog posts and news articles comments are a type of content entity and can have fields that store text html markup and other data comments are attached to other content entities via comment fields see managing content structure for more about content entities and fields  que es un tipo de comentario  los comentarios se dividen en tipos de comentarios  que son los subtipos de entidad para el tipo de entidad de comentario cada tipo de comentario tiene sus propios campos y su propia configuracion de formulario y visualizacion cada tipo se puede utilizar para comentar sobre un unico tipo de entidad puede configurar diferentes tipos de comentarios para diferentes propositos de comentarios en su sitio web por ejemplo puede configurar un tipo de comentario para recetas que tenga campos que sabor tiene y funcionaron las instrucciones y otro tipo de comentario para entradas de blog que solo tiene un campo de cuerpo de comentario generico  que es la moderacion  moderation is a workflow where comments posted by some users on your site are verified before being published to prevent spam and other bad behavior the core software provides basic moderation functionality you can configure permissions so that new comments posted by some user roles start as unpublished until a user with a different role reviews and publishes them contributed modules provide additional moderation and spamreduction functionality such as requiring untrusted users pass a captcha test before submitting comments and letting community members flag comments as possible spam see administrar cuentas de usuario y visitantes del sitio for more about users permissions and roles descripcion general de la gestion de comentarios the core comment module provides the following functionality publicacion de comentarios creating comment types the core field ui module allows you to attach fields to comment types and attach comment reference fields to other entities so that people can comment on them configuracion de comentarios comentarios moderadores como se discutio anteriormente consulte los temas relacionados listados a continuacion para tareas especificas  ', 0),
(64, 'es', 'help_search', ' adding a language objetivo agregue un idioma a su sitio pasos in the manage administrative menu navigate to configuration   region and language  idiomas haga clic en agregar idioma  if your language is in the language name list select it and click add language  if your language is not in the list select custom language  and enter the language code   language name  and direction for the language click add custom language  wait for the translation system to be updated also if you have the core update manager module installed and translations are available for your language wait for translations to be downloaded you should be returned to the languages page when this completes  ', 0);
INSERT INTO `search_dataset` (`sid`, `langcode`, `type`, `data`, `reindex`) VALUES
(65, 'es', 'help_search', ' configuracion de la deteccion y seleccion del idioma objetivo configure los metodos utilizados para decidir que lenguaje se utilizara para mostrar texto en su sitio  que es un metodo de deteccion de idiomas  a language detection method is a way for your site to decide what language should be used to display text this decision is made by evaluating a series of detection methods for languages the first detection method that gets a result will determine which language is used if you have more than one language on your site you can configure the detection methods that are used and the order they are evaluated for both user interface text and content text configuration text always uses the interface text method and most sites use the same detection methods for all types of text  que metodos de deteccion de idiomas estan disponibles  los metodos de deteccion disponibles dependen de los modulos que haya instalado algunos de los metodos de deteccion de idiomas mas utilizados son url use the language from the url which can either be in a path prefix like examplecom fr pagepath for french fr language or in a domain like frexamplecom pagepath  user for logged in users use the language they have set in their profiles navegador use las preferencias de idioma del navegador del usuario idioma seleccionado use the language most recently selected from a language switcher block sesion use the language from a session parameter or a request parameter for example adding  language fr to the end of the url pasos in the manage administrative menu navigate to configuration   region and language   languages  deteccion y seleccion marque las casillas para habilitar los metodos de deteccion de idiomas deseados y desactivar las casillas para los metodos que no desea usar arrastre los metodos para cambiar su orden si lo desea haga clic en guardar configuracion  click configure on each enabled detection method and verify that its configuration is correct or update the configuration if not  ', 0),
(66, 'es', 'help_search', ' importing a translation file objetivo import a file po extension containing translations for user interface text pasos in the manage administrative menu navigate to configuration   region and language   user interface translation  importar browse to find the translation file you want to import select the language and check the desired import options click import and wait for your file to be imported  ', 0),
(67, 'es', 'help_search', ' traducir el texto de la interfaz de usuario objetivo translate user interface text strings from english into a nonenglish language that is configured on your site pasos in the manage administrative menu navigate to configuration   region and language  traduccion de la interfaz de usuario using the filters search for a string or set of strings that you want to translate make sure to select the correct translation language if you have more than one nonenglish language on your site ingrese nuevas traducciones y haga clic en guardar traducciones  repeat these steps until all of the desired user interface text is translated for all languages on your site  ', 0),
(68, 'es', 'help_search', ' checking interface translation status objetivo verifique el estado actual de las traducciones de interfaz y vea si hay actualizaciones disponibles pasos in the manage administrative menu navigate to configuration   region and language  idiomas look at the interface translation column in the language table to find the percentage of user interface text that has been translated for each language en el menu administrativo administrar  vaya a informes   actualizaciones de traduccion disponible  este informe solo esta disponible si esta instalado el modulo principal update status optionally click check manually to update the report view the report to find out if any languages have translation updates that you can download  ', 0),
(69, 'es', 'help_search', ' using contextual links objetivo utilice enlaces contextuales para acceder a las tareas administrativas sin tener que navegar por el menu administrativo  que son los enlaces contextuales  los enlaces contextuales permiten a los usuarios que tienen el permiso para utilizar enlaces contextuales acceder rapidamente a tareas administrativas relacionadas con areas de paginas no administrativas por ejemplo si una pagina del sitio web muestra un bloque dicho bloque tendra un enlace contextual que permitira a los usuarios autorizados configurarlo si el bloque contiene un menu o una vista tambien tendra un enlace contextual para editar los enlaces del menu o la vista al hacer clic en un enlace contextual se accede directamente a la pagina de administracion relacionada sin necesidad de navegar por el sistema de menus de administracion pasos asegurese de que el modulo principal enlaces contextuales este instalado y de que dispone de un rol con el permiso usar enlaces contextuales  si lo desea asegurese de que este instalado un modulo de barra de herramientas ya sea el modulo basico barra de herramientas o un modulo de terceros alternativo visite una pagina no administrativa en su sitio como la pagina de inicio localiza un bloque u otra area en la pagina que quiera editar o configurar para que aparezca el boton de enlaces contextuales pase el cursor encima de esa zona de la pagina en la mayoria de los temas este boton tiene forma de lapiz y se situa en la esquina superior derecha del area de la pagina superior izquierda para idiomas de escritura de derecha a izquierda al pasar el cursor por encima tambien se resaltara temporalmente el area asociada como alternativa haga clic en el boton de activacion de enlaces contextuales situado en el extremo derecho de la barra de herramientas extremo izquierdo para idiomas de escritura de derecha a izquierda lo que hara visibles todos los botones de enlaces contextuales de la pagina hasta que se vuelva a hacer clic en el mientras el boton de enlaces contextuales del area de interes este visible pulse el boton para visualizar la lista de enlaces de esa area haga clic en un enlace de la lista para visitar la pagina administrativa correspondiente completa tu tarea administrativa y guarda tu configuracion o cancela la accion deberias volver a la pagina en la que comenzaste  ', 0),
(70, 'es', 'help_search', ' adding a field to an entity subtype objetivo add a field to an entity subtype see managing content structure for an overview of entity types and subtypes as well as an overview of field types pasos navegue a la pagina para administrar el subtipo de entidad al que desea agregar el campo por ejemplo para agregar un campo a un tipo de contenido en el menu administrativo administrar  vaya a estructura   tipos de contenido  find the particular subtype that you want to add the field to and click manage fields  haz clic en agregar campo  in add a new field  select the type of field you want to add see managing content structure for an overview of field types the label field should now be visible enter a label for the field which is used as the field label for both content editing and content display haz clic en guardar y continuar on the next screen enter a value for allowed number of values  you can limit the field to one value per entity item a set number of values or set it to have unlimited values click save field settings  on the next screen optionally edit the settings for the field which vary depending on what field type you are creating for all fields you can edit the label   help text  text to be displayed below the field on the content editing page and required field  to make it so a value must be entered in order to save the content when editing you can also configure a default value for the field click save settings  you should be returned to the manage fields page with your new field in the list  ', 0),
(71, 'es', 'help_search', ' configuring field display for an entity subtype objetivo configure the formatters used to display the fields of an entity subtype their order in the display and the formatter settings see managing content structure for background information pasos navegue a la pagina para administrar el tipo de entidad al que desea agregar el campo por ejemplo para agregar un campo a un tipo de contenido en el menu administrativo administrar  vaya a estructura   tipos de contenido  find the particular subtype that you want to configure the display of and click manage display in the operations list utilice las flechas de arrastrar para ordenar el area en su orden preferido drag any fields that you do not wish to see in the display to the disabled section in the label column select the position for each field label in the display or  hidden  to hide a label you can also choose  visually hidden if you want the label s text to appear in the html page so that screen readers and search engines can read it but it will not be visible in the format column select the formatter for displaying each field after selecting the desired formatters click the settings gear in each row to change the settings for the formatter cuando este haciendo cambios haga click en guardar  test the display for your entity subtype by viewing an entity if needed return to these steps to further refine the display  ', 0),
(72, 'es', 'help_search', ' configuring the edit form for an entity subtype objetivo configure the widgets used to edit the fields of an entity subtype their order on the form and the widget settings see managing content structure for background information pasos navegue a la pagina para administrar el tipo de entidad al que desea agregar el campo por ejemplo para agregar un campo a un tipo de contenido en el menu administrativo administrar  vaya a estructura   tipos de contenido  find the particular subtype that you want to configure the editing form for and click manage form display in the operations list utilice las flechas de arrastrar para ordenar el area en su orden preferido drag any fields that you do not wish to see on the editing form to the disabled section in the widget column select the widget for editing each field after selecting the desired widgets click the settings gear in each row to change the settings for the widget cuando este haciendo cambios haga click en guardar  test the editing form for your entity subtype by editing or creating an entity if needed return to these steps to further refine the form  ', 0),
(73, 'es', 'help_search', ' adding a reference field to an entity subtype objetivo anade un campo de referencia de entidad a un subtipo de entidad vease managing content structure para mas informacion sobre entidades y campos de referencia pasos navegue a la pagina para administrar el subtipo de entidad al que desea agregar el campo por ejemplo para agregar un campo a un tipo de contenido en el menu administrativo administrar  vaya a estructura   tipos de contenido  find the particular subtype that you want to add the field to and click manage fields  haz clic en agregar campo  in add a new field  select the type of reference field you want to add the reference section of the select list shows the most common types of reference field choose other  if the entity type you want to reference is not listed the label field should now be visible enter a label for the field which is used as the field label for both content editing and content display haz clic en guardar y continuar on the next screen verify that the type of entity you want to reference is shown in type of item to reference  or select it if not enter a value for allowed number of values  you can limit the field to one value per entity item a set number of values or set it to have unlimited values click save field settings  on the next screen optionally edit the settings for label   help text  text to be displayed below the field on the content editing page and required field  to make it so a value must be entered in order to save the content when editing in the reference type section you will usually want to limit the entity subtypes that can be referenced for example if you are creating a content reference you can check one or two content type choices the choices will be easier for content editors to scan if you also choose a sort value normally the entity title or label field click save settings  you should be returned to the manage fields page with your new field in the list  ', 0),
(74, 'es', 'help_search', ' tracking which content a user has visited what content visits are tracked  the core history module tracks when each loggedin user has most recently visited each content item page on the site this allows content to be marked as new or updated for each user meaning that it was newly created or has been updated since the last time they visited its page these records are kept for one month meaning that content older than one month is never marked as new or updated  cuales son las opciones disponibles para usar este rastreo de informacion  you can display the new updated status of content by creating or editing a view there is a has new content field for content views which displays the new updated marker there is also a has new content filter which limits the view to new and updated content  ', 0),
(75, 'es', 'help_search', ' configuracion de la taxonomia objetivo crea un vocabulario de taxonomia y anade un campo de referencia para ese vocabulario a una entidad de contenido consulte gestion de la taxonomia para obtener informacion sobre la taxonomia y managing content structure para obtener mas informacion sobre las entidades de contenido  quien puede configurar un vocabulario de taxonomia  users with the administrar vocabularios y terminos permission can configure a vocabulary to add a field in the administrative interface the core field ui module must be installed and you will also need the administer fields permission for the entity you are adding the field to pasos en el menu administrativo administrar  vaya a estructura   taxonomia  haz clic en agregar vocabulario  en el campo nombre  introduzca un nombre para el vocabulario por ejemplo ingredientes que es como se mostrara en la interfaz administrativa opcionalmente anada una descripcion haz clic en guardar  su vocabulario se creara y vera la pagina que enumera todos los terminos de este vocabulario opcionalmente haga clic en agregar termino para agregar un termino al nuevo vocabulario en el campo nombre  ingrese el nombre del termino por ejemplo mantequilla haga clic en guardar  recibira una confirmacion sobre el termino que creo opcionalmente puede continuar agregando mas terminos if you have the field ui module installed follow the instructions on the related adding a reference field to an entity subtype topic to add a taxonomy reference field to the entity type of your choice the settings page will allow you to choose the vocabulary that you created as the vocabulary to reference you may also want to configure the display and form display of the new field see related topics  recursos adicionales setting up a taxonomy drupal user guide  ', 0),
(76, 'es', 'help_search', ' gestion de la taxonomia  que es la taxonomia  la taxonomia se utiliza para clasificar el contenido del sitio web un ejemplo comun de taxonomia son las etiquetas utilizadas para clasificar o categorizar publicaciones en un sitio web de blog un sitio web de cocina podria usar una taxonomia de ingredientes para clasificar recetas los elementos de taxonomia individuales se conocen como terminos  las etiquetas de blog o los ingredientes de recetas en estos ejemplos y un conjunto de terminos se conoce como vocabulario  el conjunto de todas las etiquetas de publicaciones de blog o el conjunto de todos los ingredientes de recetas en estos ejemplos tecnicamente los terminos de taxonomia son un tipo de entidad y los subtipos de entidad son los vocabularios consulte managing content structure para obtener mas informacion sobre las entidades de contenido al igual que otras entidades los terminos de la taxonomia pueden tener campos adjuntos por ejemplo puede configurar un campo de imagen para que contenga un icono para cada termino un vocabulario individual puede organizar sus terminos en una jerarquia o puede ser plano por ejemplo las etiquetas de un blog suelen tener una estructura plana mientras que el vocabulario de ingredientes de una receta puede ser jerarquico por ejemplo los tomates pueden ser un subtermino de las verduras y dentro de los tomates puede haber tomates verdes y rojos los terminos de la taxonomia se adjuntan normalmente como campos de referencia a otras entidades de contenido que es como se pueden utilizar para clasificar el contenido cuando se configura un campo de referencia de taxonomia se puede permitir a los usuarios introducir terminos de dos maneras etiquetado libre se pueden crear nuevos terminos directamente en el formulario de edicion de contenidos lista fija de terminos la lista de terminos se elabora y gestiona fuera del formulario de edicion de contenidos y los usuarios solo pueden seleccionarlos de la lista existente al editar los contenidos los campos de referencia de taxonomia se pueden agregar a cualquier entidad como cuentas de usuario bloques de contenido o elementos de contenido normales si los utiliza para clasificar elementos de contenido habituales su sitio se configurara automaticamente con paginas de listado de taxonomias para cada termino cada una de estas paginas enumera todos los elementos de contenido clasificados con ese termino overview of managing taxonomy the core taxonomy module allows you to create and edit taxonomy vocabularies and taxonomy terms the core field ui module provides a user interface for adding fields to entities including the taxonomy reference field and configuring field editing and display see the related topics listed below for specific tasks recursos adicionales concept taxonomy drupal user guide  ', 0),
(77, 'es', 'help_search', ' agregar un estilo de imagen objetivo anade un nuevo estilo de imagen que puede utilizarse para procesar y mostrar imagenes consulte managing media para obtener una vision general de los estilos de imagen pasos en el menu administrativo administrar  vaya a configuracion   medios  estilos de imagen click add image style  enter a descriptive image style name  and click create new style  under effect  choose an effect to apply and click add  configure the effect on the next page most effects require some additional configuration after they are added for example for the crop effect enter the width and height to crop the image to and choose the anchor point click add effect  repita los dos pasos anteriores hasta que se hayan agregado todos los efectos arrastre para cambiar el orden de los efectos luego haga clic en guardar para guardar el nuevo pedido the image style can now be used to format a field containing an image in your layouts or traditional field displays it can also be used as part of a responsive image style see related topics below for more information  ', 0),
(78, 'es', 'help_search', ' managing content listings views  what is a view  a view is a listing of items on your site for example a block showing the most recent comments a page listing news items or a list of registered users the listings can be formatted in a table grid list calendar rss feed and other formats some output formats may require you to install additional contributed modules  what are the components of a view  when you first create a view you will specify what type of base data is being displayed in the view which cannot be changed after choosing a base data type you can edit the following components which allow you to specify which data to output in what order and in what format  displays  whether the output goes to a page block feed etc a single view can have multiple displays each with different settings format  the output style for each display such as content item grid table or html list fields  if the format allows the particular fields to display filter criteria  criteria to limit the data to output such as whether the content is published the type of content etc filters can be exposed to let users choose how to filter the data sort criteria  how to order the data sorting can also be exposed to users configuracion de pagina   configuracion de bloqueo  etc configuraciones especificas del tipo de visualizacion como la url para la visualizacion de una pagina la mayoria de los tipos de visualizacion admiten una configuracion de acceso  en la que puede elegir un permiso o una funcion que un usuario debe tener para ver la vista header and footer  content to display at the top or bottom of the view display no results behavior  what to do if the filter criteria result in having no data to display pager  how many items to display and how to paginate if there are additional items to display advanced   contextual filters  like regular filters except the criteria come from the context  such as the current date page the view is displayed on etc advanced   relationships  additional data to pull in and display related in some way to the base data of the view such as data about the user who created the content item  advanced   exposed form  if you have exposed filters or sorts how to display the form to the user what are bulk operations  views using a table display format can include a bulk operations form which allows users with sufficient permission to select one or more items from the view and apply an administrative action to them the bulk actions available are specific to the base data type of the view for example a view of content items could support bulk publishing and unpublishing actions if you have the core actions ui module installed see the related topic configuring actions for more about actions managing views overview el modulo del nucleo views vistas maneja la presentacion de vistas y el modulo del nucleo views ui interfaz de usuario de vistas permite crear editar y eliminar vistas en la interfaz de administracion mire la lista de contenidos relacionados a continuacion para obtener mas informacion sobre tareas especificas si el modulo views ui esta instalado  recursos adicionales creating listings with views drupal user guide  ', 0),
(79, 'es', 'help_search', ' configure menu settings for a content type objetivo for an existing content type configure the available menus that will be shown as options on content editing screens links to content items of this type can be added to these menus during editing pasos en el menu administrativo administrar  vaya a estructura  tipos de contenido localice el tipo de contenido que desea configurar y pulse sobre editar en la lista de operaciones  under menu settings  check the menus that you want to be available when editing a content item of this type optionally select the default parent item  to put links to content items under a default location in the menu structure pulse guardar   ', 0),
(80, 'es', 'help_search', ' adding a link to a menu objetivo anada este enlace al menu compruebe que puede anadir tambien el link a un menu desde la pagina de edicion de contenido si los ajustes del sitio web fueron ya configurados para el tipo de contenido pasos en el menu de administracion gestionar  vaya a estructura  menus locate the desired menu and click add link in the operations list enter the menu link title to be displayed enter the link  one of the following an internal path such as  node add a full external url start typing the title of a content item and select it when the full title comes up  nolink  to display the menu link title as plain text without a link  front  to link to the front page of your site make sure that enabled is checked if not the menu link will not be displayed optionally enter a description  which will be displayed when a user hovers over the link optionally check show as expanded to automatically show the children of this link if any when this link is shown optionally select the parent link  if this menu link should be a child of another menu link click save  you will be returned to the add link page to add another link en el menu de administracion gestionar  vaya a estructura  menus locate the menu you just added a link to and click edit in the operations list verify that the order of links is correct if it is not drag menu links until the order is correct and click save   ', 0),
(81, 'es', 'help_search', ' creating a menu objetivo create a new menu pasos en el menu de administracion gestionar  navegue por estructura  menus click add menu  enter the title for the menu which is used as the default block title if the menu is displayed as a block if desired also edit the machine name of the menu which is by default derived from the title enter an administrative summary which is displayed on the menus page if your site has more than one language choose the language for the menu click save  you will be on the menu editing page ready to add links to the menu if the core custom menu links module is installed see related topics for further tasks  ', 0),
(82, 'es', 'help_search', ' reordering and disabling menu links objetivo disable menu links or change the order and hierarchy of menu links pasos en el menu de administracion gestionar  vaya a estructura  menus click edit menu for the menu that you want to edit drag menu links into a new order or check uncheck enabled to enable or disable menu links click save to save your changes  ', 0),
(83, 'es', 'help_search', ' creacion de un alias de url para un elemento de contenido objetivo asigne a la pagina de un elemento de contenido un alias de url amigable para las personas o para el seo puede seguir pasos similares para crear un alias para una pagina de terminos de taxonomia consulte configuracion de alias para urls para obtener mas informacion sobre los alias  quien puede crear alias de url  los usuarios con el permiso crear y editar alias de url pueden crear alias para seguir los pasos de este tema tambien necesitara permiso para editar el elemento de contenido pasos locate and open the content edit form for the content item or create a new content item see related topics on creating and editing content under url alias on the edit form enter the desired alias for example aboutus make sure the alias starts with a character pulse guardar  compruebe que la pagina puede ser visitada con el nuevo alias por ejemplo https examplecom aboutus  recursos adicionales creating a content item drupal user guide  ', 0),
(84, 'es', 'help_search', ' edicion de un alias de url objetivo cambiar un alias de url existente para corregir la ruta o el valor del alias ver configuracion de alias para urls para mas informacion sobre los alias who can manage url aliases  users with the administrar alias de url permission can edit aliases pasos in the manage administration menu navigate to configuration   search and metadata   alias de url  a list of all the site s aliases will appear haga clic en editar en el boton desplegable para el alias que le gustaria cambiar make the required changes and click save  you will be returned to the url alias list page tenga en cuenta que tambien puede agregar nuevos alias de esta pagina para cualquier ruta en su sitio  ', 0),
(85, 'es', 'help_search', ' configuracion de alias para urls  que es una url  url is the abbreviation for uniform resource locator which is the page s address on the web it is the name by which a browser identifies a page to display in the example visit us at examplecom   https examplecom would be the url for the home page of your website users use urls to locate content on the web what is a path  a path is the unique last part of the url for a specific function or piece of content for example for a page whose full url is https examplecom node 7  the path is node 7  here are some examples of paths you might find in your site nodo 7 ruta a un elemento de contenido en particular taxonomy term 6 ruta a una pagina de terminos de taxonomia user 3 path to a user profile page  que es un alias  the core software allows you to provide more understandable urls for pages on your site which are called aliases  for example if you have an about us page with the path node 7  you can set up an alias of about so that your visitors will see it as https wwwexamplecom about  descripcion general de la configuracion de rutas alias y url the core path module provides the url aliasing functionality the contributed pathauto module allows you to configure automaticallygenerated url aliases for content items and other pages see the related topics listed below for specific tasks recursos adicionales concept paths aliases and urls drupal user guide  ', 0),
(86, 'es', 'help_search', ' creacion y uso de enlaces administrativos de acceso directo objetivo cree vea y use un conjunto de accesos directos para acceder a las paginas administrativas  que son los atajos  los accesos directos son enlaces rapidos a paginas administrativas son administrados por el modulo principal shortcut un sitio puede tener uno o mas conjuntos de accesos directos  que pueden ser compartidos por uno o mas usuarios por defecto solo hay un conjunto compartido por todos los usuarios cada conjunto contiene un numero limitado de atajos los usuarios necesitan el permiso usar accesos directos para ver los accesos directos permiso editar conjunto de accesos directos actual para anadir eliminar o editar los accesos directos en el conjunto asignado a ellos y permiso de seleccionar cualquier conjunto de accesos directos para seleccionar un conjunto de atajos diferente al editar su perfil de usuario tambien hay un permiso administrar accesos directos  que permite a un administrador realizar cualquiera de estas acciones asi como seleccionar conjuntos de accesos directos para otros usuarios pasos make sure that the core shortcut module is installed and that you have a role with edit current shortcut set or administer shortcuts permission also make sure that a toolbar module is installed either the core toolbar module or a contributed module replacement navegue a la pagina administrativa que desee en su lista de accesos directos haz clic en el enlace de acceso directo para agregar la pagina a tu lista de accesos directos en el tema administrativo principal claro el enlace se ve como una estrella y se muestra junto al titulo de la pagina sin embargo si la pagina ya esta en tu conjunto de accesos directos hacer clic en el enlace de acceso directo la eliminara de tu conjunto de accesos directos repita hasta que se hayan agregado todos los enlaces deseados a su conjunto de atajos haga clic en atajos en la barra de herramientas para mostrar sus accesos directos y verifique que la lista este completa si lo desea haga clic en editar accesos directos en el extremo derecho de la lista de accesos directos extremo izquierdo en los idiomas de derecha a izquierda para eliminar enlaces o cambiar el orden haga clic en cualquier enlace de la barra de acceso directo para ir directamente a la pagina administrativa  ', 0),
(87, 'es', 'help_search', ' adding a new display to an existing view objetivo add a new display to an existing view this will allow you to display similar data to an existing view using similar settings in a new block page feed etc pasos if you are not already editing your view in the manage administrative menu navigate to structure   vistas  find the view you want to edit and click its edit link under displays  click add  in the popup list click the link for the type of display you want to add the most common types are page and block  the new display will be added to your view and you will be editing that display optionally click the link next to display name and enter a new name to be shown for this display in the administrative interface follow the steps in editing an existing view display to edit the other settings for the display  ', 0),
(88, 'es', 'help_search', ' adding a bulk operations form to a view objetivo add one or more existing actions as bulk operations to an existing tablestyle view if you have the core actions ui module installed see the related topic configuring actions for more information about actions  quien puede modificar las vistas  the core views ui module will need to be installed and you will need administrar vistas permission in order to edit a view pasos en el menu administrativo administrar  vaya a estructura   vistas  se muestra una lista de todas las vistas busque la vista que le gustaria editar y haga clic en editar en el boton desplegable tenga en cuenta que las operaciones masivas funcionan mejor en una vista con visualizacion de pagina y formato de tabla if there is not already an operations bulk form in the fields list for the view click add in the fields section to add it the exact name of the bulk form field will vary and may contain keywords like bulk update form element or operations not to be confused with operations links  which are applied to each item in a row if the bulk operations field already exists click the field name to edit its settings check the action s you want to make available in the selected actions list and click apply all displays   verifique que la configuracion de acceso para la vista sea al menos tan restrictiva como los permisos necesarios para realizar las operaciones masivas las personas con permiso para ver la vista pero que no tienen permiso para realizar las operaciones masivas experimentaran problemas haga clic en guardar  la s accion es estara n disponible s como operaciones masivas en la vista  ', 0),
(89, 'es', 'help_search', ' creating a new view objetivo create a new view to list content or other items on your site pasos in the manage administrative menu navigate to structure   vistas  click add view  in the view name field enter a name for the view which is how it will be listed in the administrative interface in view settings   show  select the base data type to display in your view this cannot be changed later optionally select or enter filtering sorting and page block display settings these can be added or changed later click save and edit  your view will be created edit it following the steps in the related topics below  ', 0),
(90, 'es', 'help_search', ' editing an existing view display objetivo edit an existing view display to modify what data is displayed or how it is displayed pasos if you are not already editing your view in the manage administrative menu navigate to structure   vistas  find the view you want to edit and click its edit link under displays  click the display you want to edit busque la seccion cuya configuracion desea cambiar como formato o criterios de filtro  consulte managing content listings views para obtener mas informacion for sections containing lists such as fields and filter criteria  to modify or delete an existing item click the name of the item to add a new item click add in the dropdown list to change the order of items click rearrange in the dropdown list for sections containing individual settings such as title and format  there are often two links for each setting the first link shows the current value click that link to change the value if there is a second link called settings  click that link to change the settings details for example if your format is currently shown as unformatted list  click unformatted list to switch to using a grid or table format click settings next to your format type to change the settings for your chosen format when you have finished changing all the settings verify that the display is correct by clicking update preview  return to editing settings if necessary when you have verified the display click save  alternatively if you have made mistakes and want to discard your changes click cancel  recursos adicionales creating listings with views drupal user guide  ', 0);
